// ================= FILTRADO DINÁMICO DE ACTIVAS =================
// Solo se exportan facultades y provincias que cuentan con al menos 1 carrera cargada (>0).
// Las instituciones y provincias que aún tienen 0 carreras quedan ocultas automáticamente
// hasta que en el futuro se incorporen sus planes de estudio.
export const AVAILABLE_FACULTADES: FacultadOption[] = ALL_FACULTADES.filter((f) =>
  AVAILABLE_CAREERS.some((c) => c.facultad === f.id)
);

export const AVAILABLE_PROVINCIAS: ProvinciaOption[] = ALL_PROVINCIAS.filter((p) =>
  AVAILABLE_FACULTADES.some((f) => f.provinciaId === p.id)
);

